def inicializar_versoes(apps, schema_editor):
    documento = apps.get_model("legal", "DocumentoLegal")
    versao = apps.get_model("legal", "VersaoDocumentoLegal")
    banco = schema_editor.connection.alias
    contato = settings.CONTATO_PRIVACIDADE
    for tipo, (numero, vigencia, secoes) in DOCUMENTOS_INICIAIS.items():
        trechos = []
        for secao in secoes:
            trechos.append(f"## {secao['titulo']}")
            for bloco in secao["blocos"]:
                trechos.append("\n".join(f"- {item}" for item in bloco["itens"]) if "itens" in bloco else bloco["texto"])
        registro = documento.objects.using(banco).create(
            tipo=tipo, rascunho_conteudo="\n\n".join(trechos), rascunho_contato=contato,
        )
        registro.versao_vigente = versao.objects.using(banco).create(
            documento=registro, numero=numero, conteudo=secoes,
            contato=contato, vigente_desde=date(*vigencia),
        )
        registro.save(using=banco, update_fields=["versao_vigente"])


def proteger_tabelas_internas(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return

    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            "SELECT rolname FROM pg_roles WHERE rolname IN ('anon', 'authenticated', 'service_role')"
        )
        papeis = ["PUBLIC", *(schema_editor.quote_name(nome) for (nome,) in cursor.fetchall())]
        destinatarios = ", ".join(papeis)
        for nome in ("DocumentoLegal", "VersaoDocumentoLegal"):
            modelo = apps.get_model("legal", nome)
            tabela = schema_editor.quote_name(modelo._meta.db_table)
            cursor.execute(f"ALTER TABLE {tabela} ENABLE ROW LEVEL SECURITY")
            cursor.execute(f"REVOKE ALL PRIVILEGES ON TABLE {tabela} FROM {destinatarios}")
            if modelo._meta.pk.name == "id":
                cursor.execute("SELECT pg_get_serial_sequence(%s, 'id')", [tabela])
                sequencia, = cursor.fetchone()
                cursor.execute(f"REVOKE ALL PRIVILEGES ON SEQUENCE {sequencia} FROM {destinatarios}")


